/* Letter names and phonemes have separate playback and separate evidence. */
let diagnosticAudio=null,diagnosticTimer=null,heardQuestion=null,effectContext=null;
const phonemeLabels={a:'/æ/',b:'/b/',c:'/k/',d:'/d/',e:'/e/',f:'/f/',g:'/ɡ/',h:'/h/',i:'/ɪ/',j:'/dʒ/',k:'/k/',l:'/l/',m:'/m/',n:'/n/',o:'/ɑ/',p:'/p/',q:'/kw/',r:'/r/',s:'/s/',t:'/t/',u:'/ʌ/',v:'/v/',w:'/w/',x:'/ks/',y:'/j/',z:'/z/'};
function chooseFriendlyVoice(){const voices=window.speechSynthesis?.getVoices()||[];return voices.filter(v=>/^en[-_]/i.test(v.lang)).sort((a,b)=>voiceScore(b)-voiceScore(a))[0];}
function voiceScore(v){return (/en[-_]US/i.test(v.lang)?10:0)+(/Aria|Jenny|Samantha|Zira|Google US English|Ava|Emma|Serena/i.test(v.name)?20:0)+(/Natural|Online|Enhanced/i.test(v.name)?5:0);}
function stopDiagnosticAudio(){diagnosticAudio?.pause();window.speechSynthesis?.cancel();document.querySelector('.listen-orb')?.classList.remove('is-playing');}
function speakFriendly(text,onStart,onEnd){
 if(!window.speechSynthesis){toast('Голос недоступен. Открой проверку в браузере с английской озвучкой.');return false;}
 stopDiagnosticAudio();const u=new SpeechSynthesisUtterance(text);const voice=chooseFriendlyVoice();if(voice)u.voice=voice;u.lang=voice?.lang||'en-US';u.pitch=1.32;u.rate=.88;u.volume=1;
 u.onstart=()=>onStart?.();u.onend=()=>{onEnd?.();document.querySelector('.listen-orb')?.classList.remove('is-playing');};u.onerror=e=>{document.querySelector('.listen-orb')?.classList.remove('is-playing');if(!['canceled','interrupted'].includes(e.error))toast('Не удалось включить голос. Нажми «Послушать» ещё раз.');};window.speechSynthesis.speak(u);return true;
}
function playLetterName(letter,onStart){return speakFriendly('The letter '+letter.toUpperCase()+'.',onStart);}
function playLetterSound(letter,onStart){
 stopDiagnosticAudio();diagnosticAudio=new Audio('assets/phonemes/'+letter+'.mp3');diagnosticAudio.preload='auto';diagnosticAudio.playbackRate=1;
 diagnosticAudio.onplaying=()=>onStart?.();diagnosticAudio.onended=()=>document.querySelector('.listen-orb')?.classList.remove('is-playing');diagnosticAudio.onerror=()=>{toast('Звук не загрузился. Проверь соединение и повтори.');document.querySelector('.listen-orb')?.classList.remove('is-playing');};
 diagnosticAudio.play().catch(()=>{toast('Нажми на кнопку звука ещё раз.');document.querySelector('.listen-orb')?.classList.remove('is-playing');});
}
function playFeedback(correct){
 try{const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;effectContext??=new AudioCtx();effectContext.resume();const ctx=effectContext,t=ctx.currentTime;const notes=correct?[523.25,659.25,783.99]:[330,277];notes.forEach((hz,i)=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=hz;gain.gain.setValueAtTime(0,t+i*.105);gain.gain.linearRampToValueAtTime(correct?.07:.045,t+i*.105+.015);gain.gain.exponentialRampToValueAtTime(.001,t+i*.105+.2);osc.connect(gain);gain.connect(ctx.destination);osc.start(t+i*.105);osc.stop(t+i*.105+.23);});}catch{}
}
function showDiagnosticIntro(){
 showModal(`<div class="intro-orbi"><img src="assets/orbit-world.png" alt="Орби приглашает в путешествие по алфавиту"></div><div class="eyebrow">ОРБИ И МАСТЕРСКАЯ БУКВ</div><h2>У каждой буквы<br>есть имя и звук.</h2><p>Пойдём по алфавиту: <b>A → B → C → … → Z</b>. Для каждой буквы сначала найдём её по названию, затем — по отдельному звуку.</p><div class="intro-rules"><span><b>01</b> Послушай Орби</span><span><b>02</b> Выбери букву</span><span><b>03</b> Попробуй ещё раз, если нужно</span></div><p>Ошибочная буква погаснет. Мы останемся в задании, пока ты не найдёшь правильную. Все трудные места сохраним для повторения.</p><button class="primary" onclick="modal.close();startDiagnostic()">В мастерскую букв <span>↗</span></button><p class="credits-small">Звуковые образцы: <a href="https://phonicademy.com/audio-license" target="_blank" rel="noopener">Phonicademy</a>. Проверяем узнавание названий и звуков на слух.</p>`);
}
function startDiagnostic(){clearTimeout(diagnosticTimer);quiz=AssessmentCore.create();state.pendingQuiz=quiz;persist();renderDiagnostic();}
function renderDiagnostic(){
 if(quiz?.schemaVersion!==3){startDiagnostic();return;}
 clearTimeout(diagnosticTimer);stopDiagnosticAudio();heardQuestion=null;view='assessment';const q=quiz.items[quiz.index];if(!q){finishDiagnostic();return;}
 document.getElementById('crumb').textContent='Мастерская букв';
 // C and K share /k/. Never offer both as different answers to the same sound.
 const ambiguous=q.mode==='sound'&&['c','k'].includes(q.letter)?['c','k']:[];
 const previous=AssessmentCore.events(quiz,q);const wrong=previous.filter(e=>!e.correct).map(e=>e.answer);
 const options=quiz.choiceKey===AssessmentCore.key(q)&&quiz.choices?quiz.choices:shuffle([q.letter,...shuffle(alphabet.filter(l=>l!==q.letter&&!ambiguous.includes(l))).slice(0,2)]);
 quiz.choiceKey=AssessmentCore.key(q);quiz.choices=options;state.pendingQuiz=quiz;persist();
 const doneLetters=Math.floor(quiz.index/2);
 app.innerHTML=`<div class="letter-studio"><div class="studio-toolbar"><button class="text-btn" onclick="exitQuiz()">← Сделать паузу</button><span class="studio-pill">${q.mode==='name'?'НАЗВАНИЕ БУКВЫ':'ЗВУК БУКВЫ'} <b>${quiz.index+1} / 52</b></span><button class="text-btn" onclick="showAudioSettings()">♫ Голос и звук</button></div><div class="studio-progress"><div style="width:${quiz.index/52*100}%"></div></div><section class="studio-stage"><span class="studio-star star-one">✦</span><span class="studio-star star-two">✧</span><div class="orbi-bubble"><span class="orbi-face"><img src="assets/orbit-world.png" alt="Орби"></span><span>Слушай внимательно.<br><b>У тебя всё получится!</b></span></div><div class="studio-heading"><span class="eyebrow">МАСТЕРСКАЯ МАЛЕНЬКИХ ОТКРЫТИЙ</span><h1>${q.mode==='name'?'Узнаёшь моё имя?':'А теперь — мой звук!'}</h1><p>${q.mode==='name'?'Послушай название и найди букву.':'Послушай отдельный звук и найди его букву.'}</p></div><button class="listen-orb" onclick="playDiagnosticCue()" aria-label="${q.mode==='name'?'Послушать название буквы':'Послушать звук буквы'}"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M9 15h7l9-7v24l-9-7H9Z"/><path d="M30 13q8 7 0 14"/></svg><span class="sound-wave"></span></button><div class="listen-caption" id="listenCaption">Нажми, чтобы послушать ${q.mode==='name'?'название':'звук'}</div><div class="toy-answers" role="group" aria-label="Выбери букву">${options.map((l,i)=>`<button class="toy-answer toy-${i} ${wrong.includes(l)?'dimmed':''}" data-letter="${l}" aria-label="Буква ${l.toUpperCase()}" ${wrong.includes(l)?'disabled':''} onclick="answerDiagnostic('${l}',this)"><span class="toy-letter" aria-hidden="true">${l.toUpperCase()}<span class="toy-eyes"><i></i><i></i></span></span><span class="toy-lower" aria-hidden="true">${l}</span><span class="toy-floor"></span><span class="toy-success" aria-hidden="true">✦</span></button>`).join('')}</div><div id="diagnosticFeedback" class="studio-feedback" role="status" aria-live="polite">${wrong.length?'Попробуй другую букву. Мы никуда не спешим.':'Сначала послушай, потом выбирай.'}</div><div class="alphabet-trail" aria-label="Пройдено букв: ${doneLetters} из 26">${alphabet.map((l,i)=>`<span class="${i<doneLetters?'trail-done':i===doneLetters?'trail-current':''}">${i<doneLetters?l.toUpperCase():i===doneLetters?'✦':'·'}</span>`).join('')}</div><div class="studio-footnote">${q.mode==='name'?'Имя буквы и её звук проверяем отдельно.':'Один базовый звук на букву. C и K — /k/, Q — /kw/, X — /ks/.'}</div></section><div class="studio-parent-note"><span>♡</span> Результат учитывает первую попытку и каждую ошибку. Подсказки помогают учиться, но не повышают оценку.</div></div>`;
}
function playDiagnosticCue(){const q=quiz?.items[quiz.index];if(!q)return;const current=quiz,questionKey=AssessmentCore.key(q);document.querySelector('.listen-orb')?.classList.add('is-playing');const onStart=()=>{if(quiz!==current||AssessmentCore.key(quiz.items[quiz.index])!==questionKey)return;heardQuestion=questionKey;quiz.replays??={};quiz.replays[questionKey]=(quiz.replays[questionKey]||0)+1;document.getElementById('listenCaption').textContent='Ещё раз? Нажми на звук';document.getElementById('diagnosticFeedback').textContent='Теперь выбери букву.';state.pendingQuiz=quiz;persist();};if(q.mode==='name')playLetterName(q.letter,onStart);else playLetterSound(q.letter,onStart);}
function answerDiagnostic(answer,button){
 const q=quiz?.items[quiz.index];if(!q||view!=='assessment')return;const result=AssessmentCore.answer(quiz,answer,heardQuestion===AssessmentCore.key(q));
 if(!result.accepted){if(!heardQuestion){toast('Сначала послушай название или звук.');document.querySelector('.listen-orb')?.focus();}return;}
 state.pendingQuiz=quiz;persist();stopDiagnosticAudio();playFeedback(result.correct);
 if(!result.correct){button.disabled=true;button.classList.add('dimmed');document.getElementById('diagnosticFeedback').textContent='Эта буква отдыхает. Посмотри на другие — попробуй ещё!';return;}
 document.querySelectorAll('.toy-answer').forEach(b=>b.disabled=true);button.classList.add('celebrate');document.getElementById('diagnosticFeedback').textContent=q.mode==='name'?'Да! Ты нашёл букву по её имени.':'Получилось! Это её звук.';
 const current=quiz;diagnosticTimer=setTimeout(()=>{if(view!=='assessment'||quiz!==current)return;quiz.index++;state.pendingQuiz=quiz;persist();if(quiz.index<quiz.items.length)renderDiagnostic();else finishDiagnostic();},950);
}
function exitQuiz(){clearTimeout(diagnosticTimer);stopDiagnosticAudio();state.pendingQuiz=quiz;persist();showModal(`<div class="eyebrow">ПАУЗА — ТОЖЕ ЧАСТЬ ПУТИ</div><h2>Буквы тебя подождут.</h2><p>Мы сохранили ответы и все попытки. Можно продолжить с этого места.</p><button class="primary" onclick="modal.close();navigate('home')">В мой кабинет</button><button class="secondary" onclick="modal.close();renderDiagnostic()">Продолжить</button>`);}
function finishDiagnostic(){clearTimeout(diagnosticTimer);stopDiagnosticAudio();const result=AssessmentCore.summarize(quiz);if(!result.completed){renderDiagnostic();return;}state.diagnostic=result;delete state.pendingQuiz;state.sessions.push({type:'diagnostic',at:result.at,passed:result.passed,names:result.names,sounds:result.sounds,errorLetters:result.errorLetters,details:result.detail});persist();renderDiagnosticSummary(result);}
function errorTable(d){if(!d.detail)return '';const rows=d.detail.filter(x=>x.name.errors.length||x.sound.errors.length);if(!rows.length)return '<div class="all-clear">✦ Все названия и звуки найдены с первой попытки.</div>';return `<div class="mistakes-section"><h3>Вот где понадобилась ещё попытка</h3><p>Повторим эти буквы. Ни одна ошибка не потерялась.</p><div class="mistake-rows">${rows.map(x=>`<div class="mistake-row"><span class="report-letter">${x.letter.toUpperCase()}<small>${x.letter}</small></span><div><b>${x.name.errors.length?'Название: '+x.name.errors.length+' '+pluralAttempts(x.name.errors.length):'Название — с первой попытки'}</b><small>${x.name.errors.length?'Выбирал: '+x.name.errors.map(e=>e.answer.toUpperCase()).join(' → '):'Без ошибок'}</small></div><div><b>${x.sound.errors.length?'Звук: '+x.sound.errors.length+' '+pluralAttempts(x.sound.errors.length):'Звук — с первой попытки'}</b><small>${x.sound.errors.length?'Выбирал: '+x.sound.errors.map(e=>e.answer.toUpperCase()).join(' → '):'Без ошибок'}</small></div><button class="replay-small" onclick="playLetterName('${x.letter}')" aria-label="Название ${x.letter.toUpperCase()}">Имя ▷</button><button class="replay-small" onclick="playLetterSound('${x.letter}')" aria-label="Звук ${x.letter.toUpperCase()}">Звук ▷</button></div>`).join('')}</div></div>`;}
function pluralAttempts(n){return n===1?'ошибка':n<5?'ошибки':'ошибок';}
function renderDiagnosticSummary(d){app.innerHTML=`<div class="diagnostic-report"><div class="report-hero"><div class="eyebrow">ПУТЕШЕСТВИЕ A → Z ЗАВЕРШЕНО</div><div class="result-orb">✦</div><h1>${d.passed?'Первые слова уже ждут!':'У нас есть твой маршрут!'}</h1><p>Все 26 букв найдены. А теперь посмотрим,<br>какие имена и звуки ты узнал сразу.</p><div class="result-grid"><div><span class="report-tag">НАЗВАНИЯ БУКВ</span><strong>${d.names}<small> / 26</small></strong><p>с первой попытки</p></div><div><span class="report-tag">ЗВУКИ БУКВ</span><strong>${d.sounds}<small> / 26</small></strong><p>с первой попытки</p></div></div><button class="primary" onclick="continueLearning()">${d.passed?'Перейти к CVC-словам':'Повторить трудные буквы'} ↗</button><button class="text-btn" onclick="navigate('home')">В кабинет</button></div>${errorTable(d)}<div class="report-method"><b>Как считаем результат</b><p>Верный ответ после ошибки завершает задание, но не засчитывается как знание с первой попытки. Название и базовый звук имеют отдельные результаты. Это проверка узнавания на слух, не произношения. Предварительный переход к CVC: 24/26 названий и 23/26 звуков.</p></div><div class="sound-credits">Phonics sounds: <a href="https://phonicademy.com" target="_blank" rel="noopener">Phonicademy</a> · <a href="https://phonicademy.com/audio-license" target="_blank" rel="noopener">лицензия</a></div></div>`;}
function results(){const d=state.diagnostic;if(d?.schemaVersion===3){app.innerHTML=title('У каждого умения — своя история','Названия и звуки букв','Два отдельных результата. Все ошибки сохранены для повторения.');const heading=app.innerHTML;renderDiagnosticSummary(d);app.innerHTML=heading+app.innerHTML;return;}app.innerHTML=title('Начнём с точного понимания','Мои результаты','Новая диагностика отдельно проверяет названия букв и их звуки.')+`<div class="empty"><div class="result-orb">✦</div><h2>${d?'Проверим знания по-новому?':'Найдём твою точку старта'}</h2><p>Пройдём от A до Z. Ошибки сохранятся, а первый ответ определит результат.</p><button class="primary" onclick="showDiagnosticIntro()">Начать проверку ↗</button></div>`;}
function showAudioSettings(){showModal(`<div class="eyebrow">СЛУШАЕМ И ОТКРЫВАЕМ</div><h2>Голос Орби</h2><p>Названия букв звучат высоким, бодрым английским голосом. Отдельные звуки воспроизводятся из записанного набора, чтобы сохранять фонему разборчивой.</p><button class="primary" onclick="playLetterName('a')">Послушать название A</button> <button class="secondary" onclick="playLetterSound('a')">Послушать звук A</button><p>Голос названий зависит от английских голосов, установленных в браузере. Образцы звуков работают одинаково на всех устройствах.</p><p class="credits-small">Phonics sounds: <a href="https://phonicademy.com" target="_blank" rel="noopener">Phonicademy</a>, <a href="https://phonicademy.com/audio-license" target="_blank" rel="noopener">лицензия для использования в продукте</a>.</p>`);}
// Resuming after a correct response must continue at the next unanswered item.
const originalContinueLearning=continueLearning;
continueLearning=function(){if(state.pendingQuiz?.schemaVersion===3){quiz=state.pendingQuiz;while(quiz.index<quiz.items.length&&AssessmentCore.events(quiz,quiz.items[quiz.index]).some(e=>e.correct))quiz.index++;if(quiz.index>=quiz.items.length)finishDiagnostic();else renderDiagnostic();return;}originalContinueLearning();};

if(state.diagnostic && ![3,4,5].includes(state.diagnostic.schemaVersion)){state.legacyDiagnostic=state.diagnostic;state.diagnostic=null;persist();}
